def nome_foto(marca, nome, concentracao):
    """Nome do arquivo da foto. Segue a convencao '<Nome> <Marca>.jpg'.

    Luna Rossa Carbon existe em EDT e EDP: nesse caso a concentracao entra no
    nome para os dois arquivos nao colidirem.
    """
    colide = sum(1 for p in PERFUMES if p[1] == marca and p[2] == nome) > 1
    base = f"{nome} {marca} {concentracao}" if colide else f"{nome} {marca}"
    return base.replace('/', '-') + '.jpg'
